23	/**
24	 * Apply CommonMark backslash-unescaping to a raw source slice, tracking which
25	 * resulting characters came from an escape. `\#` yields a `#` flagged escaped,
26	 * so the tag lexer can tell a deliberately-escaped hash from a real tag.
27	 * Returns code points (not UTF-16 units) so astral characters stay intact.
28	 */
29	function unescapeBackslashes(source: string): { chars: string[]; escaped: boolean[] } {
30	  const codePoints = [...source];
31	  const chars: string[] = [];
32	  const escaped: boolean[] = [];
33	
34	  for (let i = 0; i < codePoints.length; i++) {
35	    if (codePoints[i] === "\\" && i + 1 < codePoints.length && isAsciiPunctuation(codePoints[i + 1])) {
36	      chars.push(codePoints[i + 1]);
37	      escaped.push(true);
38	      i++;
39	      continue;
40	    }
41	    chars.push(codePoints[i]);
42	    escaped.push(false);
43	  }
44	
45	  return { chars, escaped };
46	}
