48	/**
49	 * Split a run of characters into text/tag segments. `escaped[i]` marks a
50	 * character that came from a backslash escape: an escaped `#` can never start a
51	 * tag (so `\#NAS` stays literal text), matching the backend goldmark parser and
52	 * the editor's marked tokenizer, both of which honor the escape natively.
53	 */
54	function parseSegments(chars: string[], escaped: boolean[]): Segment[] {
55	  const segments: Segment[] = [];
56	  let i = 0;
57	
58	  while (i < chars.length) {
59	    if (chars[i] === "#" && !escaped[i] && i + 1 < chars.length && isTagChar(chars[i + 1])) {
60	      const prevChar = i > 0 ? chars[i - 1] : "";
61	      const nextChar = chars[i + 1];
62	
63	      if (prevChar === "#" || nextChar === "#" || nextChar === " ") {
64	        segments.push({ type: "text", value: chars[i] });
65	        i++;
66	        continue;
67	      }
68	
69	      let j = i + 1;
70	      while (j < chars.length && isTagChar(chars[j])) {
71	        j++;
72	      }
73	
74	      const tagContent = chars.slice(i + 1, j).join("");
75	
76	      const runeCount = [...tagContent].length;
77	      if (runeCount > 0 && runeCount <= MAX_TAG_LENGTH) {
78	        segments.push({ type: "tag", value: tagContent });
79	        i = j;
80	        continue;
81	      }
82	    }
83	
84	    // Consume a plain-text run up to the next tag-eligible (non-escaped) hash.
85	    let j = i + 1;
86	    while (j < chars.length && !(chars[j] === "#" && !escaped[j])) {
87	      j++;
88	    }
89	    segments.push({ type: "text", value: chars.slice(i, j).join("") });
90	    i = j;
91	  }
92	
93	  return segments;
94	}
