158	      const segments = segmentsForTextNode(textNode.value, textNode.position, source);
159	
160	      if (segments.every((seg) => seg.type === "text")) {
161	        continue;
162	      }
163	
164	      const newNodes = segments.map((segment) => {
165	        if (segment.type === "tag") {
166	          return createTagNode(segment.value);
167	        }
168	        return {
169	          type: "text",
170	          value: segment.value,
171	        } as Text;
172	      });
173	
174	      parent.children.splice(index, 1, ...(newNodes as UnistNode[]));
175	      index += newNodes.length - 1;
176	      continue;
177	    }
178	
179	    if (isParentNode(child)) {
180	      transformTagTextNodes(child, childInsideLink, source);
181	    }
182	  }
183	}
